SELECT payment_order_id, order_no, player_id, wallet_id, order_type, amount, currency_code, status, psp_code, psp_transaction_id, description, create_time, update_time FROM t_payment_order
AND player_id = #{query.playerId}
AND order_type = #{query.orderType}
AND status = #{query.status}
AND psp_code = #{query.pspCode}
ORDER BY payment_order_id DESC
